  'contact.hero.title':'Kontakt i dojazd','contact.hero.sub':'Pytania o pobyt, swell albo jak nas znaleźć? Odpowiadamy szybko.',
  'contact.form.title':'Napisz do nas','contact.field.name':'Twoje imię','contact.field.email':'E-mail','contact.field.subject':'Temat','contact.field.message':'Wiadomość',
